mode() { echo $1 > $H/mode; }
echo '{"issue": 1}' > $S/away-control.json
rec away c1 "{\"state\": \"away\", \"entry\": \"c1\", \"started\": \"$(iso -7200)\", \"until\": \"$(iso -3600)\", \"cap\": null, \"quiet\": false, \"words\": \"lift the hold on #7, merge-ok #9 and go full speed\"}"
c=$(caps); echo "away c1 (until passed 1h ago, no return record): $c; $(dj)"; eq "$c" "builders 1/3"; eq "$(dj)" "admit:#3"
CREW_POOL=builder $C dequeue --ref "#3" $P --timeout 10 >/dev/null && $C schedule release --pool builder "#3" $P >/dev/null && echo "ack: x" >> $S/status/builder-3.status || exit 1
$C spawn builder --issue 4 $P --timeout 10 >/dev/null && echo "ack: x" >> $S/status/builder-4.status || exit 1
for i in 5 7; do $C spawn builder --issue $i $P --timeout 10 | grep -q "^queued: builder build issue #$i" || exit 1; done
c=$(caps); echo "away, three busy: $c; $(dj); alive $(alive)"; eq "$c" "builders 3/3"; eq "$(dj)" "deferred:#5 held:#7"
w=$(grep -cE "^(issue (edit|close|reopen)|pr (merge|edit|review|ready)|label |api .*-X)" {state_dir}/gh.log); echo "forge writes after the away words: $w"; eq "$w" 0

