mode() { echo $1 > $H/mode; }
ev ask ask-9 | grep -q "Slack delivery failed; retry scheduled (attempt 1)" || exit 1
eq "$(nfy)" "ask:pending:1"; echo "refused (no listener): $(nfy)"
ev land 21 "{\"title\": \"$CAMPAIGN_WEBHOOK\"}" | grep -q "not queued: invalid event" || exit 1; eq "$(nfy)" "ask:pending:1"; echo "event carrying the webhook: not queued"
nohup python3 $H/hook.py $H </dev/null >/dev/null 2>&1 & echo $! > $H/pid; for i in $(seq 50); do [ -s $H/port ] && break; sleep 0.1; done
export CAMPAIGN_WEBHOOK="http://127.0.0.1:$(cat $H/port)/hook/SECRET-T0KEN-a25"
$C notify $P --flush 2>&1 | tee -a $H/out.log; eq "$(nfy)" "ask:pending:1"; eq "$(posts)" 0; echo "retry not yet due: no post"
due; $C notify $P --flush 2>&1 | tee -a $H/out.log; eq "$(nfy)" "ask:sent:1"; eq "$(posts)" 1
python3 -c "import json,sys; t=json.loads(open(sys.argv[1]).readline()); print(t.replace(chr(10), ' | ')); assert all(s in t for s in ('Owner decision needed', 'deadline: 2026-11-07T09:00:00-08:00', 'default: keep hold', '/issues/9')), t" $H/posts.jsonl || exit 1
ev ask ask-9 >/dev/null; $C notify $P --flush >/dev/null; eq "$(nfy)" "ask:sent:1"; eq "$(posts)" 1; echo "replayed ask-9: deduped"

